INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8b24-7c99-9b9d-7c50ce636dc3'::uuid, '019f9df7-a2a2-7865-ab8c-df9bc214c173'::uuid, 'A regular polygon has interior angle to exterior angle ratio 5:4. Explain why this is impossible.', 'The number of sides is not a whole number.', 'Let the interior angle be 5x and the exterior angle be 4x. Since they add up to 180°, 9x = 180, so x = 20 and the exterior angle is 80°. The number of sides would be 360 ÷ 80 = 4.5, which is not an integer, so such a regular polygon is impossible.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.324Z'::timestamptz, '2026-08-15T07:36:12.324Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8b38-79b0-8303-8496caf05eb0'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'Explain why x^2 - 10x + 7 has its minimum value when x = 5.', 'Because the squared term is smallest when x = 5.', 'From x^2 - 10x + 7 = (x - 5)^2 - 18, the squared term (x - 5)^2 is always at least 0. It is smallest when x = 5, so the whole expression is minimum at x = 5.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.344Z'::timestamptz, '2026-08-15T07:36:12.344Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8b3d-7b79-801b-9988a68d5e8c'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'A shopkeeper makes a loss of 24% when selling an item for $136. Find the selling price needed to make a profit of 40%.', '$250', 'If $136 is 76% of the cost price, then cost price = 136 ÷ 0.76 = 178.947... For a 40% profit, selling price = 1.4 × 178.947... = 250. So the required selling price is $250.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.349Z'::timestamptz, '2026-08-15T07:36:12.349Z'::timestamptz) ON CONFLICT (id) DO NOTHING;